UPDATE TB_PROJECT SET
      PROJ_NM = #{projNm}
    , PROJ_TYPE = #{projType}
    , STATUS = #{status}
    , START_DT = NULLIF(#{startDt},'')
    , END_DT = NULLIF(#{endDt},'')
    , M_EMP_ID = #{mainMgrId}
    , S_EMP_ID = #{subMgrId}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , EST_EFFORT = #{estEffort}
