UPDATE TB_ASSIGNMENT
   SET CONFIRM_YN = #{confirmYn}
 WHERE ASSIGN_ID = #{assignId}

UPDATE TB_ASSIGNMENT 
   SET CONFIRM_YN = #{confirmYn}
 WHERE TASK_GROUP_ID = #{taskGroupId}

