 WHERE PROJ_ID = #{projId}

UPDATE TB_ASSIGNMENT
SET
EMP_ID = #{userId},  INPUT_RATE = 1.0,    START_DT = NOW(),
END_DT = DATE_ADD(NOW(), INTERVAL 3 MONTH),
ASSIGN_TITLE = #{assignTitle}
WHERE ASSIGN_ID = #{assignId}

UPDATE TB_ASSIGNMENT SET
      ASSIGN_TITLE = #{assignTitle}
    , START_DT     = STR_TO_DATE(#{startDt}, '%Y-%m-%d')
    , END_DT       = STR_TO_DATE(#{endDt}, '%Y-%m-%d')
    , REQ_SKILLS   = #{reqSkills}
    , ASSIGN_REMARK  = #{assignRemark}
    , ATCH_FILE_ID   = #{atchFileId}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    WHERE TASK_GROUP_ID = #{taskGroupId}

